<?php

declare(strict_types=1);

namespace Unitary\Inflation;

use Brick\Math\BigRational;
use RuntimeException;
use Unitary\Currency\Currency;

/**
 * A price index read from a data file in resources/inflation/, generated by
 * bin/update-inflation-data.php from the official publisher.
 */
abstract class BundledPriceIndex implements PriceIndex
{
    /** @var array{title: string, series: string, currency: string, publisher: string, source: string, retrieved: string, annual: array<int, string>, monthly: array<string, string>}|null */
    private ?array $data = null;

    /** The data file name inside resources/inflation/. */
    abstract protected function file(): string;

    public function currency(): Currency
    {
        return Currency::from($this->data()['currency']);
    }

    public function value(int $year, ?int $month = null): ?BigRational
    {
        $data = $this->data();
        $value = $month === null
            ? ($data['annual'][$year] ?? null)
            : ($data['monthly'][sprintf('%04d-%02d', $year, $month)] ?? null);

        return $value === null ? null : BigRational::of($value);
    }

    public function firstYear(): int
    {
        $data = $this->data();
        $years = array_keys($data['annual']);

        if ($data['monthly'] !== []) {
            $years[] = (int) substr((string) array_key_first($data['monthly']), 0, 4);
        }

        return $years === [] ? throw new RuntimeException('Empty price index') : min($years);
    }

    public function latestYear(): int
    {
        return (int) substr($this->latestPeriod(), 0, 4);
    }

    public function latest(): BigRational
    {
        $monthly = $this->data()['monthly'];

        if ($monthly !== []) {
            return BigRational::of($monthly[array_key_last($monthly)]);
        }

        $annual = $this->data()['annual'];

        return BigRational::of($annual[array_key_last($annual) ?? throw new RuntimeException('Empty price index')]);
    }

    public function latestPeriod(): string
    {
        $monthly = $this->data()['monthly'];

        if ($monthly !== []) {
            return (string) array_key_last($monthly);
        }

        return array_key_last($this->data()['annual']).'-12';
    }

    public function source(): string
    {
        $data = $this->data();

        return sprintf('%s, %s (%s), retrieved %s from %s', $data['publisher'], $data['title'], $data['series'], $data['retrieved'], $data['source']);
    }

    /** The series identifier, e.g. "CUUR0000SA0". */
    public function series(): string
    {
        return $this->data()['series'];
    }

    /**
     * @return array{title: string, series: string, currency: string, publisher: string, source: string, retrieved: string, annual: array<int, string>, monthly: array<string, string>}
     */
    private function data(): array
    {
        if ($this->data === null) {
            /** @var array{title: string, series: string, currency: string, publisher: string, source: string, retrieved: string, annual: array<int, string>, monthly: array<string, string>} $data */
            $data = require dirname(__DIR__, 2).'/resources/inflation/'.$this->file();
            $this->data = $data;
        }

        return $this->data;
    }
}
